fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    if strings.is_empty() {
        return None;
    }

    // Keep track of the index of the first longest sequence
    // and a reference to that sequence
    let mut max_index = 0;
    let mut max_len = strings[0].len();

    for (i, seq) in strings.iter().enumerate().skip(1) {
        if seq.len() > max_len {
            max_len = seq.len();
            max_index = i;
        }
    }

    // Clone the sequence at max_index to return it owned
    Some(strings[max_index].clone())
}